cloudrun.run:
python3 -c "
import os, glob
for py_file in glob.glob('apps/ops-bastion/**/*.py', recursive=True):
    if not py_file.endswith('__init__.py') and os.path.isfile(py_file):
        stem = py_file[:-3]
        if os.path.isdir(stem) and any(f.endswith('.py') for f in os.listdir(stem)):
            os.remove(py_file)
" || true

